import{_ as a,o as e,c as t,a8 as s}from"./chunks/framework.BppdKxCY.js";const g=JSON.parse('{"title":"EP.17 Web 新能力","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.17-web-platform.md","filePath":"comics/EP.17-web-platform.md","lastUpdated":1792817913000}'),o={name:"comics/EP.17-web-platform.md"};function l(n,i,r,h,p,d){return e(),t("div",null,[...i[0]||(i[0]=[s(`<h1 id="ep-17-web-新能力" tabindex="-1">EP.17 Web 新能力 <a class="header-anchor" href="#ep-17-web-新能力" aria-label="Permalink to &quot;EP.17 Web 新能力&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../17-web-platform">17-web-platform.md</a>（17.1 浏览器新能力速查 / 17.2 可视化技术选型 / 17.3 Web Components）· 示例：<code>examples/17-01-popover.html</code>、<code>examples/17-05-web-component.html</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君自制下拉弹层：层叠、点外关闭、Esc、焦点、滚动锁，半周还没做全。</li><li><strong>第 2 格</strong>：码叔揭秘 Popover API：浏览器原生顶层弹层，<code>popovertarget</code> 声明即用。</li><li><strong>第 3 格</strong>：像素酱实证 View Transitions 一行 API 做转场，Web Components 三件套封装原生组件。</li><li><strong>第 4 格</strong>：码叔结案——可视化按 SVG/Canvas/WebGL 选型，WASM 只对 CPU 密集有收益。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-自制弹层的隐形成本" tabindex="-1">第 1 格 · 自制弹层的隐形成本 <a class="header-anchor" href="#第-1-格-·-自制弹层的隐形成本" aria-label="Permalink to &quot;第 1 格 · 自制弹层的隐形成本&quot;">​</a></h3><ul><li>z-index 层叠战争、滚动穿透锁定、点击外部关闭、Esc 关闭；</li><li>焦点管理、可访问性（参照 EP.15）、嵌套层级、定位翻转；</li><li>这些是「写两天、调两周」的典型功能，且每个团队重写一遍。</li></ul><h3 id="第-2-格-·-popover-api" tabindex="-1">第 2 格 · Popover API <a class="header-anchor" href="#第-2-格-·-popover-api" aria-label="Permalink to &quot;第 2 格 · Popover API&quot;">​</a></h3><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> popovertarget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;menu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;菜单&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;menu&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> popover</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;…&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li><strong>顶层（top layer）渲染</strong>：不受任何父级 overflow/z-index 影响；</li><li>自带：轻关闭（点外部/Esc）、焦点管理、<code>showPopover()</code>/<code>hidePopover()</code> 方法与 toggle/beforetoggle 事件；</li><li>与 <code>&lt;dialog&gt;</code> 的分工：dialog 是模态会话（有模态背景），popover 是非模态临时浮层。</li></ul><h3 id="第-3-格-·-view-transitions-与-web-components" tabindex="-1">第 3 格 · View Transitions 与 Web Components <a class="header-anchor" href="#第-3-格-·-view-transitions-与-web-components" aria-label="Permalink to &quot;第 3 格 · View Transitions 与 Web Components&quot;">​</a></h3><ul><li><strong>View Transitions</strong>：<code>document.startViewTransition(() =&gt; updateDOM())</code>，浏览器自动对新旧状态做截图过渡，配合 <code>::view-transition-*</code> CSS 做共享元素动画；</li><li><strong>Web Components 三件套</strong>：Custom Elements（自定义标签生命周期）+ Shadow DOM（样式与 DOM 封装）+ <code>&lt;template&gt;</code>（可复用结构），产出框架无关的组件；</li><li>浏览器正在把过去必须引框架才能做的事逐步内置。</li></ul><h3 id="第-4-格-·-可视化选型与-wasm" tabindex="-1">第 4 格 · 可视化选型与 WASM <a class="header-anchor" href="#第-4-格-·-可视化选型与-wasm" aria-label="Permalink to &quot;第 4 格 · 可视化选型与 WASM&quot;">​</a></h3><ul><li><strong>SVG</strong>：节点少、要交互/可访问性（图表、图标），DOM 事件天然可用；</li><li><strong>Canvas 2D</strong>：节点多但逻辑简单（千级散点、热力图）；</li><li><strong>WebGL/WebGPU</strong>：海量图元/3D（地图、粒子、三维），通常直接用 Three.js；</li><li><strong>WASM</strong>：适合编解码、仿真、图像处理等 CPU 密集；对 IO 等待密集场景零收益，还有加载与胶水层成本。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../17-web-platform#_17-6-本章避坑清单">《17.6 本章避坑清单》</a></p></blockquote><ol><li>所有浮层都手写：焦点/Esc/层叠/滚动锁成本极高，Popover/dialog 能覆盖就别造轮子；</li><li>图节点不多却上 Canvas：失去 DOM 可访问性与事件系统，维护成本陡增；</li><li>为&quot;性能&quot;上 WASM：瓶颈在网络/IO 时毫无收益，先 profile 再决定。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>Popover 帮你免费解决了哪些问题？——<strong>顶层渲染（无 z-index 战争）、轻关闭（点外部/Esc）、焦点管理</strong>。</li><li>Web Components 三件套是什么？——<strong>Custom Elements、Shadow DOM、&lt;template&gt;</strong>。</li><li>SVG/Canvas/WebGL 怎么选？——<strong>少量可交互节点选 SVG；大量 2D 图元选 Canvas；海量图元或 3D 选 WebGL/WebGPU</strong>。</li></ol>`,19)])])}const k=a(o,[["render",l]]);export{g as __pageData,k as default};
